{//MilkDrop3 Rotate Mode:
uv = uv.yx;
//MilkDrop3 Flip Mode:
uv = 1.0 - uv;
ret = texture(sampler_main, uv).xyz;
float L = lum(ret);
float bw = clamp01(cos(L * 27.0 + 3) * 30.0 - 26);
float L2 = lum(GetBlur1(uv));
float bw2 = clamp01(cos(L * 27.0 + 3) * 3.0 - 6);
ret = vec3(.1,.6,1.1)*ret.x +
vec3(.1,.6,.55)*ret.y +
vec3(1.5,.6,.2)*ret.z;
ret = ret*ret * (.5 + bw*bw2 * 1.0);
//MilkDrop3 Color Mode:
ret /= vec3(1.0,1.1,1.2);
ret -=0.1;
}

